# SteadyScreen installer for Windows -- ASSEMBLED FILE, DO NOT EDIT.
# Built from build/windows/{gui,Preflight-SteadyScreen,New-PayloadPartition,Arm-SteadyScreen,Reset-SteadyScreenArming}.ps1
# by build/windows/make-launcher.sh on 2026-09-21T21:28:09-05:00
#
# Edit the parts, run make-launcher.sh, commit both.

$SS_EMBEDDED = @{
  'Preflight-SteadyScreen.ps1' = ''
  'New-PayloadPartition.ps1' = ''
  'Arm-SteadyScreen.ps1' = ''
  'Reset-SteadyScreenArming.ps1' = ''
}

<#
    SteadyScreen installer for Windows.

    Converts the machine it runs on into a SteadyScreen display. THE DISK IS
    ERASED. There is no undo, which is why the button below is dead until
    somebody has said so in as many words.

    Launched the way winutil is:

        irm https://steadyscreen.com/win | iex

    from an elevated PowerShell, or from a ScreenConnect toolbox item running
    that same line. There is no installer and nothing is left behind except the
    payload it downloads, and that goes with the disk.

    THIS FILE IS ASSEMBLED. build/windows/make-launcher.sh embeds the three
    proven scripts -- Preflight, New-PayloadPartition, Arm -- as base64 and
    drops this in front of them. They are written to disk and invoked exactly
    the way they are today, byte for byte, because they are the part that has
    been run against real hardware and this is the part that has not.
#>
$ErrorActionPreference = 'Stop'

# TLS 1.2, before anything downloads.
#
# Windows PowerShell 5.1 takes its default from .NET, and on plenty of
# still-supported Windows builds that default is SSL3 and TLS 1.0. GitHub --
# and every other host worth talking to -- refused those years ago, so the
# request dies with "Could not create SSL/TLS secure channel". Reported from a
# real machine on 2026-09-03, on the very first line the technician runs.
#
# It has to be set here as well as in the one-liner: the one-liner only covers
# fetching THIS file. Every download after it -- 750 MB of payload through
# Net.WebClient and HttpWebRequest -- goes through the same
# ServicePointManager, and on that machine every one of them would have failed
# the same way, several minutes later, with the disk already repartitioned.
#
# 3072 is Tls12 as a number. The named enum member does not exist on .NET 4.0,
# and naming it there throws before it can help anyone.
try {
    [Net.ServicePointManager]::SecurityProtocol =
        [Net.ServicePointManager]::SecurityProtocol -bor 3072
} catch { }

# Running scripts, in THIS process.
#
# The window writes its four helper scripts to disk and runs them as files,
# because they are the part that has been proven against real hardware and
# running them any other way would mean the tested thing and the shipped thing
# are not the same thing. A default PowerShell refuses to load a script FILE:
#
#     ...cannot be loaded because running scripts is disabled on this system.
#
# The launcher itself arrives through `iex`, which is not a file, so it runs
# happily and then dies on its own helpers. Reported from a real machine on
# 2026-09-03, from an ALREADY ELEVATED prompt -- which is why it had not been
# seen before: the elevation re-launch passes -ExecutionPolicy Bypass, and the
# ScreenConnect toolbox item passes it too, so every path that had been tested
# carried it and the one a technician types by hand did not.
#
# Process scope only. Nothing on this machine is changed for any other process
# or after this one exits -- and the machine is about to be erased anyway.
try {
    Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force -ErrorAction Stop
} catch {
    # A Group Policy can forbid even the process scope. Setting the variable
    # the process scope is stored in is the same thing by another door; if a
    # policy blocks that too, so would -ExecutionPolicy Bypass on a command
    # line, and there is nothing left to try.
    $env:PSExecutionPolicyPreference = 'Bypass'
}

$SS_BASE   = 'https://github.com/S07734/steadyscreen-releases/releases/latest/download'
$SS_HOME   = 'C:\ProgramData\SteadyScreen'
$SS_BIN    = "$SS_HOME\bin"
# Stamped by make-launcher.sh at assembly time. 'dev' means this file was run
# straight out of the checkout rather than assembled, which is worth being
# able to tell apart at a glance.
#
# It exists because of a real half hour spent asking "is that machine running
# the fix, or a cached copy of yesterday's launcher?" -- a question the tool
# should answer about itself rather than one somebody has to work out from
# byte counts. It is on the window and it is the first line of the log.
$SS_VERSION = '1.15.19+20260921-2128'
$SS_ONELINE = '[Net.ServicePointManager]::SecurityProtocol=3072; irm https://steadyscreen.com/win | iex'

# ---------------------------------------------------------------- elevation
#
# Everything here needs it: the Wi-Fi key, BitLocker, shrinking C:, the ESP,
# bcdedit. Without it the first check fails and the window reads as broken
# rather than as needing a right-click.
#
# Re-launched by RUNNING THE ONE-LINER AGAIN rather than by re-running a file,
# because when this arrives through `iex` there is no file to re-run.
if (-not ([Security.Principal.WindowsPrincipal] `
          [Security.Principal.WindowsIdentity]::GetCurrent()
         ).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Host "SteadyScreen installer needs administrator rights -- asking for them."
    # Carry SS_SCREENCONNECT_SERVER across the elevation. A RunAs relaunch gets a
    # FRESH environment, so a variable the caller set (a toolbox, a .bat) before
    # elevation would be dropped and the display would silently not enrol. From
    # ScreenConnect this branch does not run (the agent is already SYSTEM), but a
    # technician double-clicking a .bat hits it -- so forward the value into the
    # elevated command rather than trust the environment to survive.
    $fwd = ''
    if ($env:SS_SCREENCONNECT_SERVER) {
        $v = $env:SS_SCREENCONNECT_SERVER -replace "'", "''"
        $fwd = "`$env:SS_SCREENCONNECT_SERVER='$v'; "
    }
    Start-Process powershell -Verb RunAs -ArgumentList @(
        '-NoProfile','-ExecutionPolicy','Bypass','-Command', $fwd + $SS_ONELINE)
    return
}

# ------------------------------------------------------------- the scripts
# $SS_EMBEDDED is filled in by make-launcher.sh: name -> base64 of the file.
New-Item -ItemType Directory -Force -Path $SS_BIN | Out-Null
foreach ($n in $SS_EMBEDDED.Keys) {
    [System.IO.File]::WriteAllBytes("$SS_BIN\$n",
        [Convert]::FromBase64String($SS_EMBEDDED[$n]))
}

# A record, because this runs on machines nobody can see.
#
# Everything the window shows also goes to a file. A technician on the phone
# can read it, and so can anybody working out afterwards why a conversion did
# not happen. Without it the only evidence is a screenshot of a scrolling panel,
# which is how a blank field just cost a round trip to find.
$SS_LOG = "$SS_HOME\installer.log"
function Log($m) {
    try { Add-Content -Path $SS_LOG -Value ("{0}  {1}" -f (Get-Date -Format 's'), $m) } catch { }
}
Log "----- installer $SS_VERSION launched on $env:COMPUTERNAME as $env:USERNAME -----"

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase

[xml]$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        Title="SteadyScreen Installer" Height="720" Width="900"
        WindowStartupLocation="CenterScreen" Background="#111820">
  <Window.Resources>
    <!-- No implicit TextBlock style. An implicit style applies inside CONTROL
         TEMPLATES too, so a foreground meant for the dark panel was being
         painted on the light default buttons, and all three read as blank
         white rectangles. Every TextBlock below states its own colour. -->
    <!-- Explicit, not inherited. A TextBox in a dark window takes its colours
         from the system theme, so what it looks like depends on the machine
         rather than on this file, and "the box appears empty" is impossible
         to tell apart from "the value was never set" over a webcam. -->
    <Style TargetType="TextBox">
      <Setter Property="Background" Value="#0D1117"/>
      <Setter Property="Foreground" Value="#E6EDF3"/>
      <Setter Property="BorderBrush" Value="#30475E"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="CaretBrush" Value="#6FE3F2"/>
      <Setter Property="FontFamily" Value="Consolas"/>
      <Setter Property="FontSize" Value="13"/>
    </Style>
    <!-- Foreground and Background stated, because the implicit TextBlock style
         above LEAKS INTO CONTROL TEMPLATES. A Button renders its content
         through a ContentPresenter, which uses a TextBlock, which picked up
         the near-white foreground meant for the dark panel and painted it on
         a light default button. Three buttons, all reading as blank white
         rectangles, and nothing in the code looked wrong. -->
    <!-- Our own template. The system one greys a disabled button until it is
         unreadable, and the button that matters most here spends nearly all of
         its life disabled: somebody has to be able to READ what they are not
         allowed to press yet. Dimmed to 45%, not erased. -->
    <Style TargetType="Button">
      <Setter Property="Padding" Value="14,7"/>
      <Setter Property="Margin" Value="0,0,8,0"/>
      <Setter Property="FontFamily" Value="Segoe UI"/>
      <Setter Property="Background" Value="#21313F"/>
      <Setter Property="Foreground" Value="#E6EDF3"/>
      <Setter Property="BorderBrush" Value="#3A5266"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Template">
        <Setter.Value>
