  </Window.Resources>
  <Grid Margin="16">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="*"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>

    <StackPanel Grid.Row="0" Margin="0,0,0,12">
      <TextBlock FontSize="22" FontFamily="Segoe UI" Foreground="#E6EDF3"><Run Text="Steady" FontWeight="Bold"/><Run Text="Screen" Foreground="#6FE3F2" FontWeight="Bold"/><Run Text="  installer"/></TextBlock>
      <TextBlock Name="Sub" Foreground="#8B98A5" Margin="0,4,0,0"
                 Text="Turns this computer into a display. Checking what it can do..."/>
      <TextBlock Name="Ver" Foreground="#6B7681" FontFamily="Consolas" FontSize="11"
                 Margin="0,4,0,0" Text=""/>
    </StackPanel>

    <Grid Grid.Row="1">
      <Border BorderBrush="#243040" BorderThickness="1" CornerRadius="4" Padding="10">
        <ScrollViewer VerticalScrollBarVisibility="Auto">
          <StackPanel Name="Checks"/>
        </ScrollViewer>
      </Border>
      <!-- Over the panel, not beside it. The checks freeze the window while
           they run, so something has to say plainly that the tool is working
           and not hung. Sits in the same grid cell as the panel it covers. -->
      <!-- The install, once it is running. Covers everything, because from the
           moment somebody says yes there is nothing else on this window worth
           looking at, and nothing they should be able to press. -->
      <Border Name="Work" CornerRadius="4" Background="#F2111820"
              BorderBrush="#E5484D" BorderThickness="1" Visibility="Collapsed">
        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center" MaxWidth="640">
          <TextBlock Name="WorkStep" Text="Starting" FontSize="24" Foreground="#6FE3F2"
                     HorizontalAlignment="Center" FontFamily="Segoe UI" TextAlignment="Center"/>
          <TextBlock Name="WorkDetail" Foreground="#8B98A5" Margin="0,8,0,0" FontFamily="Consolas"
                     HorizontalAlignment="Center" TextAlignment="Center" TextWrapping="Wrap"/>
          <ProgressBar Name="WorkBar" Width="520" Height="10" Margin="0,18,0,0" Minimum="0" Maximum="100"
                       Background="#243040" Foreground="#6FE3F2" BorderThickness="0"/>
          <TextBlock Name="WorkPct" Foreground="#6FE3F2" Margin="0,6,0,0" FontFamily="Consolas"
                     HorizontalAlignment="Center"/>
          <TextBlock Name="WorkDone" Foreground="#3FB950" Margin="0,16,0,0" FontFamily="Consolas"
                     TextAlignment="Left" HorizontalAlignment="Center"/>
          <TextBlock Text="Do not switch this computer off." Foreground="#FF6169" FontWeight="Bold"
                     FontFamily="Segoe UI" Margin="0,18,0,0" HorizontalAlignment="Center"/>
          <!-- A read-only TextBox, not a TextBlock, so the technician can
               select the ssh line and the password and copy them. A label
               cannot be selected, and typing a 16-char password off a screen
               by hand is exactly what someone does at the worst moment. -->
          <TextBox Name="WorkPass" IsReadOnly="True" BorderThickness="0" Background="Transparent"
                   Foreground="#6B7681" FontFamily="Consolas" FontSize="11"
                   IsReadOnlyCaretVisible="True" Margin="0,12,0,0"
