                     Foreground="#6FE3F2" HorizontalAlignment="Center"/>
          <TextBlock Foreground="#8B98A5" Margin="0,10,0,0" MaxWidth="560"
                     TextWrapping="Wrap" TextAlignment="Center"
                     Text="Firmware, Secure Boot, BitLocker, memory, disks, Wi-Fi, and whether Windows has updates waiting. This takes a few seconds and the window will not respond while it runs."/>
          <ProgressBar IsIndeterminate="True" Width="340" Height="6" Margin="0,20,0,0"
                       Background="#243040" Foreground="#6FE3F2" BorderThickness="0"/>
        </StackPanel>
      </Border>
    </Grid>

    <Grid Grid.Row="2" Margin="0,12,0,0">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/>
      </Grid.ColumnDefinitions>
      <!-- No "Display name" field. It set the identity's friendly name, which
           is metadata the fleet page and portal do not show; they show the
           hardware-derived hostname (ds-hwid), and the setup screen now shows
