$win = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml))
$ui = @{}
foreach ($n in 'Sub','Ver','Checks','Busy','BusyText','Work','WorkStep','WorkDetail','WorkBar','WorkPct','WorkDone','WorkPass','Url','UrlFrom','Name','Consent','ChanStable','ChanTesting','WipeWarn','NotReady','NotReadyWhy','Recheck','Install','Close','Status') {
    $ui[$n] = $win.FindName($n)
}
# On the window from the moment it opens, so a screenshot of a failure carries
# the version of the thing that failed.
$ui.Ver.Text = "installer $SS_VERSION"
$win.Title = "SteadyScreen Installer $SS_VERSION"

function New-DetailLine($text, $kind) {
    $tb = New-Object Windows.Controls.TextBlock
    $tb.TextWrapping = 'Wrap'; $tb.Margin = '0,1,0,1'
    $tb.FontFamily = New-Object Windows.Media.FontFamily 'Consolas'
    switch ($kind) {
        'ok'   { $tb.Text = "ok    $text";   $tb.Foreground = '#3FB950' }
        'warn' { $tb.Text = "warn  $text";   $tb.Foreground = '#D29922' }
        'stop' { $tb.Text = "STOP  $text";   $tb.Foreground = '#FF6169'; $tb.FontWeight = 'Bold' }
        default{ $tb.Text = $text;           $tb.Foreground = '#8B98A5' }
    }
    return $tb
}

# One collapsible section per check, closed unless it has something to say.
#
# The flat report was forty-four lines, of which about six ever matter. A
# technician had to read a scrolling wall to find out that everything was fine,
# and the one line that was not fine looked exactly like the rest. Sections
# that passed collapse to a single green tick; anything with a warning or a
# blocker opens itself and stays open.
function Add-Section($title, $lines) {
    # Wrapped, because a section that cannot be drawn must not cost the reader
    # every other section. The detail still reaches the log either way.
    try { Add-SectionInner $title $lines }
    catch {
        Add-Line ("$title (could not be drawn: $($_.Exception.Message))") 'warn'
        foreach ($l in $lines) { Add-Line $l.Text $l.Kind }
    }
}

function Add-SectionInner($title, $lines) {
    $worst = 'ok'
    foreach ($l in $lines) {
        if ($l.Kind -eq 'stop') { $worst = 'stop'; break }
        if ($l.Kind -eq 'warn') { $worst = 'warn' }
    }
    $glyph, $colour = switch ($worst) {
        'stop' { [char]0x2717, '#FF6169' }   # a cross
        'warn' { [char]0x0021, '#D29922' }   # a bang
        default{ [char]0x2713, '#3FB950' }   # a tick
    }

    # A Grid, not a StackPanel.
    #
    # A horizontal StackPanel hands its children infinite width, so a headline
    # with TextTrimming never trims -- it just runs off the edge of the panel
    # and is cut mid-word with no ellipsis to say so. The third column is star
    # sized, which is what finally gives the text something to be too long FOR.
    $head = New-Object Windows.Controls.Grid
    # Written the long way on purpose: [Windows.GridLength]::Auto is a static
    # property that cannot be mistyped, and the star column is constructed with
    # the enum rather than a string the converter might or might not accept.
    # This runs on somebody's machine after an elevation prompt, and a throw
    # here takes the whole checklist with it.
    $cAuto1 = New-Object Windows.Controls.ColumnDefinition
    $cAuto1.Width = [Windows.GridLength]::Auto
    $cAuto2 = New-Object Windows.Controls.ColumnDefinition
    $cAuto2.Width = [Windows.GridLength]::Auto
    $cStar  = New-Object Windows.Controls.ColumnDefinition
    $cStar.Width = New-Object Windows.GridLength(1, [Windows.GridUnitType]::Star)
    $head.ColumnDefinitions.Add($cAuto1) | Out-Null
    $head.ColumnDefinitions.Add($cAuto2) | Out-Null
    $head.ColumnDefinitions.Add($cStar)  | Out-Null
    $g = New-Object Windows.Controls.TextBlock
    $g.Text = "$glyph "; $g.Foreground = $colour; $g.FontWeight = 'Bold'
    $g.FontFamily = New-Object Windows.Media.FontFamily 'Segoe UI'
    $g.Width = 22
    $t = New-Object Windows.Controls.TextBlock
    $t.Text = $title; $t.Foreground = '#E6EDF3'
    $t.FontFamily = New-Object Windows.Media.FontFamily 'Segoe UI'
    if ($worst -ne 'ok') { $t.FontWeight = 'Bold' }
    [Windows.Controls.Grid]::SetColumn($g, 0)
    [Windows.Controls.Grid]::SetColumn($t, 1)
    $head.Children.Add($g) | Out-Null
    $head.Children.Add($t) | Out-Null

    # The headline sits on the closed row, so a collapsed section still says
    # what it found. A tick with nothing beside it is a section somebody has to
    # open to learn anything from, which defeats the point of closing it.
    #
    # But a section with a warning is ALREADY OPEN, and its full text is on the
    # next line. Putting the same paragraph in the header too just gives it
    # somewhere to be truncated -- the reader sees half a sentence above the
    # whole sentence. So an open section gets a count, and a closed one gets
    # the line worth reading.
    $nStop = @($lines | Where-Object { $_.Kind -eq 'stop' }).Count
    $nWarn = @($lines | Where-Object { $_.Kind -eq 'warn' }).Count
    if ($worst -eq 'ok') {
        $summary = ($lines | Where-Object { $_.Kind -eq 'ok' } | Select-Object -First 1).Text
    } else {
        $bits = @()
        if ($nStop) { $bits += "$nStop " + $(if ($nStop -eq 1) { 'blocker' } else { 'blockers' }) }
        if ($nWarn) { $bits += "$nWarn " + $(if ($nWarn -eq 1) { 'warning' } else { 'warnings' }) }
        $summary = ($bits -join ', ') + ' -- see below'
    }
    if ($summary) {
        $st = New-Object Windows.Controls.TextBlock
        $st.Text = "   $summary"; $st.Foreground = '#7D8996'
        $st.FontFamily = New-Object Windows.Media.FontFamily 'Segoe UI'
        # One line, ended with an ellipsis. The whole point of a closed section
        # is that it fits on its row; the rest is inside, one click away.
        $st.TextTrimming = 'CharacterEllipsis'
        $st.TextWrapping = 'NoWrap'
        $st.VerticalAlignment = 'Center'
        [Windows.Controls.Grid]::SetColumn($st, 2)
        $head.Children.Add($st) | Out-Null
    }

    $body = New-Object Windows.Controls.StackPanel
    $body.Margin = '24,4,0,8'
    $body.HorizontalAlignment = 'Stretch'
    foreach ($l in $lines) { $body.Children.Add((New-DetailLine $l.Text $l.Kind)) | Out-Null }

    $ex = New-Object Windows.Controls.Expander
    $ex.Header = $head
    $ex.Content = $body
    $ex.Foreground = '#E6EDF3'
    $ex.Margin = '0,2,0,2'
    # Without this the header is sized to its content and the star column has
    # nothing to fill, so the trimming above would still never fire.
    $ex.HorizontalContentAlignment = 'Stretch'
    $ex.IsExpanded = ($worst -ne 'ok')
    $ui.Checks.Children.Add($ex) | Out-Null

    Log ("[{0}] {1}" -f $worst, $title)
    foreach ($l in $lines) { Log ("    {0,-5} {1}" -f $l.Kind, $l.Text) }
}

# Free-standing lines, for the things that are not part of a section.
function Add-Line($text, $kind) {
    $ui.Checks.Children.Add((New-DetailLine $text $kind)) | Out-Null
    Log ("{0,-5} {1}" -f $kind, $text)
}

# The install button obeys TWO conditions and both are necessary: the machine
# has to be able to take it, and a person has to have said so. Wired to one
# function so a future change cannot satisfy one and forget the other.
$script:CanInstall = $false
function Update-InstallButton {
    $ui.Install.IsEnabled = ($script:CanInstall -and $ui.Consent.IsChecked)
}

# Show the overlay, let it PAINT, then do the work.
#
# The checks run on the UI thread, so anything started in the same turn as the
# Visibility change never appears -- WPF has not had a chance to render before
# the thread is busy for the next half minute. A one-shot timer hands control
# back to the dispatcher first, which is the difference between an overlay that
# shows and one that exists only in the code.
$script:CheckTimer = $null
function Start-Checks {
    $ui.Busy.Visibility = 'Visible'
    $ui.Status.Text = ''
    $ui.Install.IsEnabled = $false
    $ui.WipeWarn.Visibility = 'Collapsed'
    $ui.NotReady.Visibility = 'Collapsed'
    $ui.Sub.Text = 'Checking what this computer can do...'
    $ui.Sub.Foreground = '#8B98A5'
    # Consent is about a set of facts. Re-checking produces new facts, so the
    # tick does not carry over -- a machine can stop being eligible between one
    # check and the next.
    $ui.Consent.IsChecked = $false
    $script:CheckTimer = New-Object Windows.Threading.DispatcherTimer
    $script:CheckTimer.Interval = [TimeSpan]::FromMilliseconds(150)
    $script:CheckTimer.Add_Tick({
        $script:CheckTimer.Stop()
        try     { Invoke-Checks }
        finally { $ui.Busy.Visibility = 'Collapsed' }
    })
    $script:CheckTimer.Start()
}

function Invoke-Checks {
    $ui.Checks.Children.Clear()
    $script:CanInstall = $false
    Update-InstallButton

    # Undo anything a previous attempt left armed, BEFORE checking anything.
    #
    # If this window is running then Windows booted, and if Windows booted the
    # install did not happen -- so an armed boot entry is by definition stale.
    # Leaving it means the machine boots the installer on every power cycle
    # with nobody there to choose otherwise, which is the failure the whole
    # disarm design exists to prevent and which the scheduled task missed the
    # one time it ran.
    try {
        $reset = & "$SS_BIN\Reset-SteadyScreenArming.ps1" 2>&1 | Select-Object -Last 1
        if ($reset -and $reset.FoundSomething) {
            Add-Line ("cleared up after an earlier attempt: " + ($reset.Actions -join ', ')) 'say'
            Log ("reset: " + ($reset.Actions -join ', '))
        }
        if ($reset -and -not $reset.WindowsFirst) {
            Add-Line 'this computer is still set to boot the installer first, and that could not be undone' 'warn'
            Log 'reset: WINDOWS IS NOT FIRST'
        }
    } catch {
        Log "reset failed: $($_.Exception.Message)"
    }

    # -IgnorePendingUpdates always (owner, 2026-09-02). Staged updates are a
    # warning here, not a refusal, because the arming step stops Windows Update
    # taking the reboot -- and that was measured, not assumed: with 8,913 MB
    # staged and both wuauserv and TrustedInstaller refusing to stop, the
    # restart still reached the installer in eighty seconds.
    #
    # It stays VISIBLE as a warning. If Arm cannot disable the services it says
    # "COULD NOT DISABLE" and the restart may be taken after all, and somebody
    # who never saw that updates were pending has no idea why the machine went
    # to Windows Update instead.
    #
    # -InstallMode REMOTE, always (owner, 2026-09-02).
    #
    # "Local" means a person is at the machine and no network is their call to
    # make -- so the installer ASKS, and waits. The owner was driving this over
    # a remote session, deliberately pretending not to be near the box, which is
    # the real case: a technician clicks yes and walks away, or was never there.
    # An installer that stops at a question nobody will answer is worse than one
    # that gives up, because giving up puts Windows back.
    #
    # Remote mode needs a way to reach a run that stalls, which is why the
    # preflight refuses it without one. The window generates a password for the
    # LIVE INSTALLER ONLY and shows it, so a stall past the point of no return
    # -- where returning to Windows is no longer possible -- is still a machine
    # somebody can ssh into rather than one nobody can.
    if (-not $script:LivePass) {
        $script:LivePass = -join ((48..57) + (65..90) + (97..122) |
            Get-Random -Count 16 | ForEach-Object { [char]$_ })
        Log "live installer password for this run: $script:LivePass"
    }
    $sec = ConvertTo-SecureString $script:LivePass -AsPlainText -Force
    $r = & "$SS_BIN\Preflight-SteadyScreen.ps1" -InstallMode remote `
              -InstallPassword $sec -IgnorePendingUpdates -AsObject 6>$null
    # Ia32 (is this 32-bit UEFI?) is decided by the firmware and does not change
    # between runs, so keep it from this preflight and hand it to the worker.
    # Otherwise the worker ran a WHOLE second preflight -- pending-updates scan
    # and all -- just to read this one flag, which was slow and muddied the log
    # with a second checklist (the "NOT SAFE TO INSTALL" report, run without a
    # password, that has confused every reading of these logs).
    $script:Ia32 = [bool]$r.Ia32
    # Blockers first. The report reads top to bottom like the console version,
    # which means the one line that decides anything ends up below the fold in
    # a panel that has to be scrolled -- and the reason a machine was refused is
    # not something to make somebody go looking for.
    # Grouped into sections, in the order the preflight produced them. Lines
    # before the first heading are the preamble and are simply dropped: they
    # are the banner, and the window has its own.
    $title = $null; $bucket = @()
    foreach ($line in $r.Report) {
        if ($line.Kind -eq 'head') {
            if ($title) { Add-Section $title $bucket }
            $title = $line.Text; $bucket = @()
        } elseif ($title -and $line.Text.Trim()) {
            $bucket += $line
        }
    }
    if ($title) { Add-Section $title $bucket }

    # The URL out of C:\kioskurl.txt, which is where these machines keep it.
    # Say which, because a page appearing in the box with no explanation is a
    # value nobody can check, and a machine WITHOUT the file looks identical to
    # one where reading it failed.
    # No C:\kioskurl.txt is not a fault (owner). Most machines will not have
    # one; the box is there to type into. Showing it as a warning put a bang
    # next to a machine that was perfectly fine, and a warning that fires on
    # the normal case is one people learn to ignore.
    #
    # Where the URL came from is still worth saying, so it goes beside the box
    # as a caption rather than into the checklist -- a prefilled field with no
    # explanation is a value nobody can check.
    if (-not $ui.Url.Text) {
        if (Test-Path 'C:\kioskurl.txt') {
            $ui.Url.Text = (Get-Content 'C:\kioskurl.txt' -Raw).Trim()
            $ui.UrlFrom.Text = 'from C:\kioskurl.txt'
            Log "page came from C:\kioskurl.txt"
        } else {
            $ui.UrlFrom.Text = ''
            Log "no C:\kioskurl.txt; the page has to be typed"
        }
    }
    Log ("page='{0}'" -f $ui.Url.Text)
    $script:CanInstall = [bool]$r.CanInstall
    if ($r.CanInstall) {
        $ui.Sub.Text = 'This computer CAN be converted.'
        $ui.Sub.Foreground = '#3FB950'
        $ui.NotReady.Visibility = 'Collapsed'
        $ui.WipeWarn.Visibility = 'Visible'
        $ui.Status.Text = ''
    } else {
        $n = $r.Blockers.Count
        $ui.Sub.Text = "This computer CANNOT be converted yet."
        $ui.Sub.Foreground = '#F0B429'
        $ui.NotReadyWhy.Text = if ($n -eq 1) { $r.Blockers[0] }
                               else { "$n things have to be dealt with first." }
        $ui.WipeWarn.Visibility = 'Collapsed'
        $ui.NotReady.Visibility = 'Visible'
        $ui.Status.Text = ''
    }
    Update-InstallButton
}

$ui.Recheck.Add_Click({ Start-Checks })
$ui.Consent.Add_Checked({ Update-InstallButton })
$ui.Consent.Add_Unchecked({ Update-InstallButton })
$ui.Close.Add_Click({ $win.Close() })

$ui.Install.Add_Click({
    # Asked twice on purpose. The checkbox is consent; this is the last moment
    # somebody can realise they are at the wrong machine.
    $answer = [Windows.MessageBox]::Show(
        "This will erase $env:COMPUTERNAME completely and install SteadyScreen.`n`n" +
        "Windows, every file and every program on this computer will be gone.`n`n" +
        "There is no undo. Continue?",
        'Erase this computer?', 'YesNo', 'Warning')
    if ($answer -ne 'Yes') { $ui.Status.Text = 'cancelled'; return }
    Start-Install
})

# ---------------------------------------------------------------- the install
#
# Yes is the cue. From here the tool does the whole thing and the window shows
# what it is doing, because 750 MB over somebody's broadband is minutes of
# apparently nothing, and a technician who cannot tell a working download from
# a hung one will power-cycle the machine.
#
# The work runs in a SEPARATE RUNSPACE. The checks get away with blocking the
# UI thread for half a minute; a download cannot, because a progress bar that
# does not move is worse than no progress bar at all. The runspace writes into
# a synchronized hashtable and a dispatcher timer on the UI thread reads it.
function Start-Install {
    $ui.Busy.Visibility = 'Collapsed'
    $ui.Work.Visibility = 'Visible'
    # Put a REAL address in the recovery line, not a "<the address it shows>"
    # placeholder that reads like a bug. This runs in Windows before the reboot,
    # so we cannot know the address the Linux installer will get -- but it keeps
    # the same NIC and DHCP lease, so its current IPv4 is almost always the one
    # it comes back on. Show that, and say to confirm it on screen.
    $ip = $null
    try {
        $ip = (Get-NetIPConfiguration -ErrorAction Stop |
               Where-Object { $_.IPv4DefaultGateway -and $_.NetAdapter.Status -eq 'Up' } |
               Select-Object -First 1).IPv4Address.IPAddress
    } catch { }
    if (-not $ip) {
        $ip = (Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue |
               Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254.*' } |
               Select-Object -First 1 -ExpandProperty IPAddress)
    }
    if (-not $ip) { $ip = 'the address it shows on screen' }
    $ui.WorkPass.Text = "If this stops, the installer can be reached with:`n" +
                        "ssh root@$ip   (confirm this on the installer's own screen)`n" +
                        "password: $script:LivePass"
    $ui.Recheck.IsEnabled = $false
    $ui.Install.IsEnabled = $false
    $ui.Close.IsEnabled = $false
    $ui.Url.IsEnabled = $false
    $ui.Consent.IsEnabled = $false
    Log "----- install started -----"

    # $script:, not local.
    #
    # A DispatcherTimer's Add_Tick scriptblock runs in its OWN scope when it
    # fires; it does not close over the locals of the function that created it.
    # So every one of these read as $null in the handler: $sync.Finished was
    # never true, the bar never moved, and the countdown never started -- while
    # the runspace behind it downloaded 750 MB, verified it, unpacked it, wrote
    # the answer file and armed the machine perfectly. The work was fine and
    # the window said nothing, which is the worst pairing available.
    $script:Sync = [hashtable]::Synchronized(@{
        Step = 'Starting'; Detail = ''; Percent = 0; Done = @(); Finished = $false
        Failed = $false;   Error = ''; Indet = $true
    })

    $work = {
        # The runspace writes the log itself. It cannot call the window's Log
        # function -- different runspace, different session state -- and the
        # first run proved why that matters: the work succeeded end to end and
        # the log recorded nothing between "install started" and the drive
        # letter, so there was no way to tell a finished install from a stuck
        # one without walking to the machine.
        # NOTHING IN HERE MAY EVER PROMPT.
        #
        # This runs in a runspace created with no host, so there is nobody to
        # ask. Anything that wants an answer -- a cmdlet's ShouldProcess
        # confirmation, or a mandatory parameter that arrived empty -- dies
        # with "A command that prompts the user failed because the host
        # program ... does not support user interaction", which names the host
        # and not the question, and suggests running it in the ISE. Reported
        # from a real machine on 2026-09-03, mid-install, on a remote site.
        #
        # Giving the runspace the console host would let the prompt through
        # instead -- and an unattended remote install would then HANG on a
        # question nobody is there to see, which is worse than stopping. So:
        # no prompts, and every value checked before it is passed on.
        $ConfirmPreference = 'None'
        $ProgressPreference = 'SilentlyContinue'

        function Say2($m) {
            try { Add-Content -Path $LOGF -Value ("{0}  {1}" -f (Get-Date -Format 's'), $m) } catch { }
        }
        # Run a helper script and put EVERYTHING it says into the log.
        #
        # The helpers report their progress with Write-Host, which in this
        # runspace goes nowhere at all -- so when New-PayloadPartition.ps1
        # failed 59 seconds into shrinking a disk on a live remote install,
        # the log held one line saying the step had started and nothing
        # whatever about where inside it the failure was. Diagnosing it meant
        # reading the script and guessing.
        #
        # No stream redirection: stream 6 is PowerShell 5 and up, and this has
        # to run on PowerShell 4 -- Windows 8.1 is exactly the vintage of
        # machine being converted. The helpers write straight into the same
        # log this does, tagged with which one is speaking, so their progress
        # is already there and nothing needs catching.
        function RunPart {
            param([string] $Script, [object[]] $Params = @())
            & "$BIN\$Script" @Params
        }

        function Note($step, $detail, $pct) {
            $sync.Step = $step; $sync.Detail = $detail
            if ($null -ne $pct) { $sync.Percent = $pct; $sync.Indet = $false }
            Say2 ("step: {0} {1}" -f $step, $detail)
        }
        function Tick($m) { $sync.Done += $m; Say2 ("done: {0}" -f $m) }

        # Old store boxes have a STALE root store and cannot validate GitHub's
        # certificate chain -- "Could not establish trust relationship for the
        # SSL/TLS secure channel" -- so the payload download fails on a machine
        # that is otherwise fine (TLS 1.2 negotiates; it is purely trust). Seen
        # converting the Irving Blvd Pipo, 2026-09-17: offline long enough that
        # its roots predate the two the download hosts chain to --
        #   github.com          -> USERTrust ECC Certification Authority
        #   *.githubusercontent -> ISRG Root X1
        # certutil -generateSSTFromWU is not dependable here (it returned
        # ACCESS_DENIED on that box). So carry the exact roots and add them
        # ourselves before the first download. Both are self-signed public roots
        # valid to 2038/2035; each is added only if the decoded bytes match the
        # known SHA1 thumbprint, and Add is idempotent -- a current machine
        # already trusts them and this is a no-op. Needs the elevation the
        # preflight already required (LocalMachine\Root is admin-only).
        function Ensure-Roots {
            $roots = @(
              ,@('ISRG Root X1','CABD2A79A1076A31F21D253635CB039D4329A5E8','')
              ,@('USERTrust ECC','D1CBCA5DB2D52A7F693B674DE5F05A1D0C957DF0','')
            )
            $store = $null
            try {
                $store = New-Object Security.Cryptography.X509Certificates.X509Store('Root','LocalMachine')
                $store.Open('ReadWrite')
            } catch { Say2 ('roots: cannot open the machine root store -- ' + $_.Exception.Message); return }
            foreach ($r in $roots) {
                try {
                    $c = New-Object Security.Cryptography.X509Certificates.X509Certificate2(,[Convert]::FromBase64String($r[2]))
                    if ($c.Thumbprint -ne $r[1]) { Say2 ('roots: ' + $r[0] + ' thumbprint mismatch -- NOT adding'); continue }
                    $store.Add($c)
                    Say2 ('roots: ' + $r[0] + ' present')
                } catch { Say2 ('roots: ' + $r[0] + ' failed -- ' + $_.Exception.Message) }
            }
            try { $store.Close() } catch { }
        }
        try {
            # Making room comes first, and it is the one step with no progress
            # to report -- Resize-Partition takes as long as it takes and says
            # nothing on the way.
            $sync.Indet = $true
            Note 'Making room on the disk' 'shrinking Windows and creating the installer partition' $null
            # It returns the drive letter rather than the caller going looking
            # for a volume with the right label: a label is not an identity,
            # and the thing that decided which partition is ours is the thing
            # that should say where it is.
            $part = RunPart 'New-PayloadPartition.ps1' | Select-Object -Last 1
            if (-not $part -or -not $part.DriveLetter) { throw 'no installer partition could be prepared' }
            $KB = $part.DriveLetter
            # Checked here, not left to be discovered by the arming step.
            #
            # -PayloadDir is the only mandatory parameter in the whole chain,
            # and PowerShell's answer to a mandatory parameter that arrives
            # empty is to PROMPT -- which in this runspace is a failure whose
            # message mentions hosts and the ISE and never mentions the drive
            # letter that was missing. Say what actually went wrong.
            if (-not $KB) {
                throw ("the installer partition was made but has no drive " +
                       "letter, so there is nowhere to put the payload. " +
                       "Check Disk Management for a 2 GB FAT32 partition " +
                       "labelled KIOSKBOOT with no letter assigned.")
            }
            if ($part.Created) { Tick "made the installer partition at $KB" }
            else               { Tick "reusing the installer partition at $KB" }

            $live = "$KB\live"; $soft = "$KB\software"
            New-Item -ItemType Directory -Force -Path $live, $soft | Out-Null

            # ---- the payload. Streamed, so the byte count is real rather than
            # a spinner that means "still alive, probably".
            # shimx64.efi + grubx64.efi + grub.cfg replaced the single
            # ssgrub.efi: a standalone GRUB carries its config inside itself
            # and is signed by nobody, so it could never boot a machine with
            # Secure Boot on -- which is how Windows 11 machines ship.
            # Which loader this machine needs, decided once, by the preflight.
            #
            # A 32-bit UEFI machine cannot execute shimx64.efi at all, so
            # downloading the x64 pair for it would be 3.7 MB over a shop's
            # wifi to stage something its firmware refuses. It takes the
            # unsigned i386-efi GRUB and the env file that makes the menu's
            # one-shot work.
            # Passed in from the checks' preflight -- NOT a second full preflight
            # here just to read one flag (that was a whole extra run, and its
            # password-less report is the "NOT SAFE TO INSTALL" noise in the log).
            $ia32 = [bool]$IA32
            $names = if ($ia32) {
                'vmlinuz','initrd.img','filesystem.squashfs','software.zip',
                'grubia32.efi','steadyscreen.env','grub.cfg'
            } else {
                'vmlinuz','initrd.img','filesystem.squashfs','software.zip',
                'shimx64.efi','grubx64.efi','grub.cfg'
            }
            if ($ia32) { Say2 '32-bit UEFI: taking the 32-bit loader' }
            # Make sure this machine can validate the download hosts' chain
            # before the first byte -- a stale root store is why an otherwise
            # healthy old Pipo fails here (see Ensure-Roots).
            Ensure-Roots
            Note 'Reading the file list' '' 0
            $sums = @{}
            foreach ($l in ((New-Object Net.WebClient).DownloadString("$BASE/PAYLOAD-SHA256SUMS") -split "`n")) {
                if ($l -match '^([0-9a-f]{64})\s+(\S+)') { $sums[$Matches[2]] = $Matches[1] }
            }
            foreach ($n in $names) { if (-not $sums[$n]) { throw "the published checksums do not list $n" } }

            $total = 0; $sofar = 0
            $sizes = @{}
            foreach ($n in $names) {
                $r = [Net.HttpWebRequest]::Create("$BASE/$n"); $r.Method = 'HEAD'
                $resp = $r.GetResponse(); $sizes[$n] = $resp.ContentLength; $resp.Close()
                $total += $sizes[$n]
            }
            foreach ($n in $names) {
                $dest = if ($n -eq 'software.zip') { "$soft\software.zip" }
                        elseif ($n -like '*.efi' -or $n -eq 'grub.cfg' -or
                                $n -eq 'steadyscreen.env') { "$KB\$n" }
                        else { "$live\$n" }
                # Already here and already right? Then it is done. An install
                # interrupted after 700 of 750 MB should not start again from
                # nothing -- that is the run most likely to be interrupted a
                # second time.
                if (Test-Path $dest) {
                    Note 'Checking what is already here' $n $null
                    if ((Get-FileHash $dest -Algorithm SHA256).Hash.ToLower() -eq $sums[$n]) {
                        $sofar += $sizes[$n]
                        $sync.Percent = [math]::Round(($sofar / $total) * 70)
                        Say2 "already downloaded and correct: $n"
                        continue
                    }
                    Say2 "re-downloading $n (present but does not match)"
                }
                Note 'Downloading the installer' "$n" $null
                $req = [Net.HttpWebRequest]::Create("$BASE/$n")
                $rs = $req.GetResponse().GetResponseStream()
                $fs = [IO.File]::Create($dest)
                $buf = New-Object byte[] 1048576
                while (($read = $rs.Read($buf, 0, $buf.Length)) -gt 0) {
                    $fs.Write($buf, 0, $read); $sofar += $read
                    $sync.Percent = [math]::Round(($sofar / $total) * 70)
                    $sync.Detail = "{0}   {1:N0} MB of {2:N0} MB" -f $n, ($sofar/1MB), ($total/1MB)
                }
                $fs.Close(); $rs.Close()
            }
            Tick 'downloaded the installer'

            # ---- and prove it arrived intact, before anything is changed.
            Note 'Checking what was downloaded' '' 72
            foreach ($n in $names) {
                $dest = if ($n -eq 'software.zip') { "$soft\software.zip" }
                        elseif ($n -like '*.efi' -or $n -eq 'grub.cfg' -or
                                $n -eq 'steadyscreen.env') { "$KB\$n" }
                        else { "$live\$n" }
                $sync.Detail = $n
                $h = (Get-FileHash $dest -Algorithm SHA256).Hash.ToLower()
                if ($h -ne $sums[$n]) { throw "$n does not match its published checksum" }
            }
            Tick 'checksums match the published release'

            Note 'Unpacking' 'software.zip' 76
            # NOT Expand-Archive. That arrived in PowerShell 5.0, in the
            # Microsoft.PowerShell.Archive module, and does not exist on
            # PowerShell 4 -- Windows 8.1, exactly the vintage of machine this
            # tool converts. Failed at 76%, on a live machine, with "The term
            # 'Expand-Archive' is not recognized".
            #
            # System.IO.Compression.ZipFile is the .NET API underneath it and
            # has been there since .NET 4.5, which every version of Windows
            # this tool supports already carries. Load the assembly (PS 4 does
            # not autoload extension methods the way 5.1 does) and call it
            # directly -- no cmdlet, no module, one fewer thing that only
            # exists on the newer half of the machines this runs on.
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            # ExtractToDirectory throws if a file it is about to write already
            # exists -- unlike Expand-Archive -Force, it has no overwrite of
            # its own. A resumed install (this machine's fourth or fifth
            # attempt, more than once today) can have a partial extraction
            # left over from a run that died after this step started. Clear
            # anything but the zip itself before extracting into it.
            Get-ChildItem $soft -Force | Where-Object { $_.Name -ne 'software.zip' } |
                Remove-Item -Recurse -Force
            [IO.Compression.ZipFile]::ExtractToDirectory("$soft\software.zip", $soft)
            Remove-Item "$soft\software.zip" -Force
            if (-not (Test-Path "$soft\manifest.json")) { throw 'software.zip did not contain a manifest' }
            Tick 'unpacked the software'

            Note 'Writing the answer file' '' 80
            $sec = ConvertTo-SecureString $LivePass -AsPlainText -Force
            # SS_SCREENCONNECT_SERVER, set by the owner's private ScreenConnect
            # toolbox item, turns on first-boot enrolment into that console.
            # Unset -- which is every public one-liner -- leaves it empty, so no
            # instance name is ever carried in a script anyone can fetch.
            $out = & "$BIN\Preflight-SteadyScreen.ps1" -InstallMode remote `
                       -InstallPassword $sec -IgnorePendingUpdates `
                       -ScreenConnectServer ([string]$env:SS_SCREENCONNECT_SERVER) `
                       -Channel $Channel `
                       -KioskUrl $KUrl -OutFile "$KB\kiosk-answers.conf" 2>&1
            if (-not (Test-Path "$KB\kiosk-answers.conf")) {
                throw "the answer file was not written: $($out -join '; ')"
            }
            Tick 'wrote the answer file'

            Note 'Preparing the firmware' 'staging the boot loader and arming' 88
            $armLoader = if ($ia32) { 'grubia32.efi' } else { 'shimx64.efi' }
            $out = & "$BIN\Arm-SteadyScreen.ps1" -PayloadDir "$KB" -Loader $armLoader 2>&1
            if ($out -match 'REFUSING') { throw ($out -join '; ') }
            Tick 'armed the next boot'

            Note 'Restarting' 'this computer will restart into the installer' 100
            $sync.Finished = $true
        } catch {
            $sync.Failed = $true
            $sync.Error = $_.Exception.Message
            $sync.Finished = $true
        }
    }

    # NOTHING blocks the UI thread from here on. Shrinking C: took seventeen
    # seconds on the bench and ran before the overlay had painted, so the window
    # sat there looking dead at exactly the moment somebody has just consented
    # to having their computer erased.
    $script:Rs = [runspacefactory]::CreateRunspace()
    $script:Rs.ApartmentState = 'STA'; $script:Rs.ThreadOptions = 'ReuseThread'; $script:Rs.Open()
    $script:Rs.SessionStateProxy.SetVariable('sync',  $script:Sync)
    $script:Rs.SessionStateProxy.SetVariable('BASE',  $SS_BASE)
    $script:Rs.SessionStateProxy.SetVariable('BIN',   $SS_BIN)
    $script:Rs.SessionStateProxy.SetVariable('LOGF',  $SS_LOG)
    $script:Rs.SessionStateProxy.SetVariable('KUrl',  $ui.Url.Text)
    $script:Rs.SessionStateProxy.SetVariable('LivePass', $script:LivePass)
    # Read on the UI thread, here, because the worker runspace cannot touch a
    # control. Stable unless Testing was explicitly picked.
    $script:Rs.SessionStateProxy.SetVariable('Channel',
        $(if ($ui.ChanTesting.IsChecked) { 'testing' } else { 'stable' }))
    # Ia32 comes from the checks' preflight (above), so the worker never re-runs it.
    $script:Rs.SessionStateProxy.SetVariable('IA32', [bool]$script:Ia32)
    $script:Psh = [powershell]::Create(); $script:Psh.Runspace = $script:Rs
    $script:Psh.AddScript($work) | Out-Null
    $script:Handle = $script:Psh.BeginInvoke()

    $script:WorkTimer = New-Object Windows.Threading.DispatcherTimer
    $script:WorkTimer.Interval = [TimeSpan]::FromMilliseconds(250)
    $script:WorkTimer.Add_Tick({
        $ui.WorkStep.Text   = $script:Sync.Step
        $ui.WorkDetail.Text = $script:Sync.Detail
        $ui.WorkBar.IsIndeterminate = [bool]$script:Sync.Indet
        $ui.WorkBar.Value   = $script:Sync.Percent
        $ui.WorkPct.Text    = if ($script:Sync.Indet) { '' } else { "$($script:Sync.Percent)%" }
        $ui.WorkDone.Text   = ($script:Sync.Done | ForEach-Object { [char]0x2713 + " $_" }) -join "`n"
        if (-not $script:Sync.Finished) { return }
        $script:WorkTimer.Stop()
        try { $script:Psh.EndInvoke($script:Handle) | Out-Null } catch { }
        $script:Psh.Dispose(); $script:Rs.Close()
        if ($script:Sync.Failed) {
            $ui.WorkStep.Foreground = '#FF6169'
            $ui.WorkStep.Text = 'The install could not go ahead'
            $ui.WorkDetail.Text = $script:Sync.Error
            $ui.WorkBar.IsIndeterminate = $false
            $ui.WorkBar.Foreground = '#FF6169'
            $ui.Close.IsEnabled = $true
            Log "FAILED: $($script:Sync.Error)"
            return
        }
        Log 'armed; restarting'
        Start-Restart
    })
    $script:WorkTimer.Start()
}

# A visible countdown rather than a machine that simply goes dark. Anybody
# standing there should be able to see the restart coming and why.
function Start-Restart {
    $script:Left = 10
    $ui.WorkStep.Text = 'Restarting into the installer'
    $ui.WorkBar.IsIndeterminate = $true
    $script:RebootTimer = New-Object Windows.Threading.DispatcherTimer
    $script:RebootTimer.Interval = [TimeSpan]::FromSeconds(1)
    $script:RebootTimer.Add_Tick({
        $ui.WorkDetail.Text = "This computer restarts in $script:Left seconds and will erase itself."
        if ($script:Left -le 0) {
            $script:RebootTimer.Stop()
            $ui.WorkDetail.Text = 'Restarting now.'
            Log 'rebooting'
            Start-Process shutdown -ArgumentList '/r','/t','0','/f' -WindowStyle Hidden
            return
        }
        $script:Left--
    })
    $script:RebootTimer.Start()
}

# Paint first, THEN check.
#
# The checks take the better part of a minute -- Windows Update's staged files
# alone are thousands of them -- and running them before ShowDialog meant forty
# seconds of nothing at all on screen. Watched happen: the task was running,
# the tool was working, and the desktop was empty. A technician would have
# double-clicked it again.
$win.Add_ContentRendered({ Start-Checks })
$win.ShowDialog() | Out-Null
